-- Three Word templates were replaced without refreshing their variable lists,
-- so generation stopped with "Las variables del Word original no coinciden":
--   * Venta condicional de vehículo con financiamiento de seguro (two library
--     copies): the buyer's name, cédula and address now appear once, not twice.
--   * Pagaré auténtico (Inversiones Indriago Martínez): the Word uses the
--     installment and amount-in-words markers instead of the old summary ones.
-- Each list below is read from the current Word. A row changes only while its
-- contract still points to that exact file; elsewhere this changes nothing.
UPDATE yzy_contracts.templates t
SET native_variables = '[{"key": "empresa_razon_social", "occurrences": 2}, {"key": "empresa_rnc", "occurrences": 1}, {"key": "empresa_direccion", "occurrences": 1}, {"key": "empresa_representante_nombre", "occurrences": 2}, {"key": "empresa_representante_ocupacion", "occurrences": 1}, {"key": "empresa_representante_cedula", "occurrences": 1}, {"key": "empresa_representante_direccion", "occurrences": 1}, {"key": "nombre_completo_del_cliente", "occurrences": 1}, {"key": "nacionalidad_del_cliente", "occurrences": 1}, {"key": "ocupacion_del_cliente", "occurrences": 1}, {"key": "cedula_del_cliente", "occurrences": 1}, {"key": "domicilio_del_cliente", "occurrences": 1}, {"key": "fecha_de_vencimiento_de_la_cuota_1", "occurrences": 1}, {"key": "monto_de_cada_cuota", "occurrences": 10}, {"key": "fecha_de_vencimiento_de_la_cuota_2", "occurrences": 1}, {"key": "fecha_de_vencimiento_de_la_cuota_3", "occurrences": 1}, {"key": "fecha_de_vencimiento_de_la_cuota_4", "occurrences": 1}, {"key": "fecha_de_vencimiento_de_la_cuota_5", "occurrences": 1}, {"key": "fecha_de_vencimiento_de_la_cuota_6", "occurrences": 1}, {"key": "fecha_de_vencimiento_de_la_cuota_7", "occurrences": 1}, {"key": "fecha_de_vencimiento_de_la_cuota_8", "occurrences": 1}, {"key": "fecha_de_vencimiento_de_la_cuota_9", "occurrences": 1}, {"key": "fecha_de_vencimiento_de_la_cuota_10", "occurrences": 1}, {"key": "tipo_del_vehiculo", "occurrences": 1}, {"key": "marca_del_vehiculo", "occurrences": 1}, {"key": "modelo_del_vehiculo", "occurrences": 1}, {"key": "anio_del_vehiculo", "occurrences": 1}, {"key": "color_del_vehiculo", "occurrences": 1}, {"key": "placa_del_vehiculo", "occurrences": 1}, {"key": "numero_de_chasis_del_vehiculo", "occurrences": 1}, {"key": "numero_de_serie_del_motor", "occurrences": 1}, {"key": "monto_total_financiado_en_letras", "occurrences": 1}, {"key": "monto_total_financiado", "occurrences": 1}, {"key": "hora_limite_para_el_pago", "occurrences": 1}, {"key": "dias_de_gracia_para_el_pago", "occurrences": 1}, {"key": "porcentaje_de_mora_diaria_sobre_la_cuota", "occurrences": 1}, {"key": "porcentaje_por_uso_del_vehiculo_al_rescindir", "occurrences": 1}, {"key": "ciudad_del_tribunal_competente", "occurrences": 2}, {"key": "periodo_de_revision_de_la_tasa_en_meses", "occurrences": 1}, {"key": "dias_de_aviso_para_revisar_la_tasa", "occurrences": 1}, {"key": "fecha_de_firma", "occurrences": 1}, {"key": "nombre_del_notario", "occurrences": 1}]'::jsonb
FROM yzy_contracts.contracts c
WHERE c.id = t.contract_id
  AND t.id IN ('3d6ab8b3-ed12-489a-bf01-2cc16f0b4940', '8f4c7091-2f0a-448b-82a4-741b0d30afc0')
  AND c.object_etag = '"16be2885772144ffc39ed50efb7fe4a2"';

